?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ask Annotated · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/research.php">Research</a><a href="/search.php">Search</a><a href="/settings.php">Settings</a></nav></header><main class="panel"><div class="pageTitle"><span class="eyebrow">PRO RESEARCH INTELLIGENCE</span><h1>Ask Annotated</h1><p>AI works over your permission-scoped research graph and is instructed to cite Annotated Source and Annotation IDs rather than inventing evidence.</p></div><?php if(!$isPro):?><div class="card"><h2>Pro feature</h2><p>Ask Annotated is available to Pro accounts. Core annotation, social, preservation and manual research remain available on Free.</p></div><?php else:?><div class="sourceGrid"><?php foreach($projects as $p):?><a class="card sourceCard" href="/research-project.php?id=<?=h($p['public_id'])?>"><span class="eyebrow">PROJECT</span><h2><?=h($p['title'])?></h2><p>Open the project and ask questions against its sources, annotations and transcripts.</p></a><?php endforeach?></div><?php if(!$projects):?><div class="card empty">Create a research project first, then add sources or annotations.</div><?php endif?><?php endif?></main></body></html>
